sys_script_include.script:
function AiToolUpdateBusinessProcess(inputs)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetValue = x_snc_devtools.GetValue;
	var ParseJson = x_snc_devtools.ParseJson;
	var IsObject = x_snc_devtools.IsObject;
	var MakeJson = x_snc_devtools.MakeJson;

	var grBP = GetBusinessProcessRecord(GetValue(inputs,'business_process'));
	if (IsValidRecord(grBP) == false)
	{
		return { message: 'The Business Process could not be found.' };
	}
	var details = ParseJson(inputs.details);
	if (IsObject(details) == false)
	{
		return { message: 'The Business Process details are not provided as a valid JSON string' };
	}
	grBP.json = MakeJson(details);
	grBP.summary = GetValue(details,'description');
	var bSuccess = grBP.update();

	if (bSuccess == false)
	{
		return { message: 'Updating the Business Process details failed!' };
	}
	return { message: 'Updating the Business Process details was successful!' };
}
